contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint probe) public {
        require(probe >= 0);
        uint b0 = address(c).balance;
        uint v0;
        bool reverted;
        uint256 v = c.pastBlockTime(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            v0 = v;
        }
        uint b1 = address(c).balance;
        assert(!reverted && v0 == 0 && b1 == b0);
    }
    receive() external payable {}
}

